script:
var boxes = [].slice.call(document.querySelectorAll("#otp input"));
var verify = document.getElementById("verify");
var resend = document.getElementById("resend");

function sync() {
  var complete = boxes.every(function (b) { return b.value !== ""; });
  verify.disabled = !complete;
  verify.classList.toggle("opacity-40", !complete);
  verify.classList.toggle("cursor-not-allowed", !complete);
}

boxes.forEach(function (box, i) {
  box.setAttribute("inputmode", "numeric");
  box.setAttribute("autocomplete", i === 0 ? "one-time-code" : "off");

  box.addEventListener("input", function () {
    box.value = box.value.replace(/\D/g, "").slice(0, 1);
    if (box.value && i < boxes.length - 1) boxes[i + 1].focus();
    sync();
  });

  box.addEventListener("keydown", function (e) {
    if (e.key === "Backspace" && !box.value && i > 0) boxes[i - 1].focus();
    if (e.key === "ArrowLeft" && i > 0) boxes[i - 1].focus();
    if (e.key === "ArrowRight" && i < boxes.length - 1) boxes[i + 1].focus();
  });

  // A pasted code should fill the whole row, not just the box under the cursor.
  box.addEventListener("paste", function (e) {
    e.preventDefault();
    var digits = (e.clipboardData || window.clipboardData).getData("text").replace(/\D/g, "");
    if (!digits) return;
    for (var k = 0; k < boxes.length; k++) boxes[k].value = digits.charAt(i + k) || boxes[k].value;
    boxes[Math.min(i + digits.length, boxes.length - 1)].focus();
    sync();
  });
});

var left = 30;
var tick = setInterval(function () {
  left -= 1;
  if (left > 0) {
    resend.textContent = "Didn't get it? Resend in 0:" + (left < 10 ? "0" + left : left);
    return;
  }
  clearInterval(tick);
  resend.textContent = "Didn't get it? ";
  var again = document.createElement("button");
  again.className = "font-medium text-neutral-900 underline";
  again.textContent = "Resend code";
  again.addEventListener("click", function () {
    boxes.forEach(function (b) { b.value = ""; });
    boxes[0].focus();
    sync();
  });
  resend.appendChild(again);
}, 1000);

sync();

var pw = document.getElementById("pw");
var confirm = document.getElementById("confirm");
var segments = [].slice.call(document.querySelectorAll("#meter span"));
var strength = document.getElementById("strength");
var submit = document.getElementById("submit");
var rules = [].slice.call(document.querySelectorAll("[data-rule]"));

var LABELS = ["—", "Weak", "Fair", "Good", "Strong"];

function check(value, other) {
  return {
    length: value.length >= 12,
    number: /[0-9]/.test(value),
    symbol: /[^A-Za-z0-9]/.test(value),
    match: value.length > 0 && value === other
  };
}

function render() {
  var value = pw.value;
  var passed = check(value, confirm.value);

  // Score the password itself; "match" is a gate on submit, not a strength signal.
  var score = 0;
  if (passed.length) score += 1;
  if (passed.number) score += 1;
  if (passed.symbol) score += 1;
  if (/[a-z]/.test(value) && /[A-Z]/.test(value)) score += 1;
  if (!value) score = 0;

  segments.forEach(function (seg, i) {
    var filled = i < score;
    seg.className =
      "h-1.5 flex-1 rounded-full " +
      (!filled ? "bg-neutral-200" : score >= 4 ? "bg-green-500" : score >= 2 ? "bg-amber-500" : "bg-red-500");
  });

  strength.textContent = LABELS[score];

  rules.forEach(function (row) {
    var ok = passed[row.getAttribute("data-rule")];
    row.className = "flex items-center gap-2 " + (ok ? "text-green-600" : "text-neutral-400");
    row.querySelector("[data-icon]").textContent = ok ? "✓" : "•";
  });

  var ready = passed.length && passed.number && passed.symbol && passed.match;
  submit.disabled = !ready;
  submit.classList.toggle("opacity-40", !ready);
  submit.classList.toggle("cursor-not-allowed", !ready);
}

pw.addEventListener("input", render);
confirm.addEventListener("input", render);
render();

var secret = document.getElementById("secret");
var copySecret = document.getElementById("copySecret");
var code = document.getElementById("code");
var verify = document.getElementById("verify");
var pairing = document.getElementById("pairing");
var done = document.getElementById("done");
var copyCodes = document.getElementById("copyCodes");

// One helper so both copy buttons behave the same way.
function copy(text, button, label) {
  navigator.clipboard.writeText(text).then(function () {
    var original = button.textContent;
    button.textContent = label;
    setTimeout(function () { button.textContent = original; }, 1600);
  });
}

copySecret.addEventListener("click", function () {
  copy(secret.textContent.replace(/\s/g, ""), copySecret, "Copied");
});

code.addEventListener("input", function () {
  code.value = code.value.replace(/\D/g, "").slice(0, 6);
  var ready = code.value.length === 6;
  verify.disabled = !ready;
  verify.classList.toggle("opacity-40", !ready);
  verify.classList.toggle("cursor-not-allowed", !ready);
});

verify.addEventListener("click", function () {
  // Enrolment succeeded — the recovery codes are the last thing left to do.
  pairing.classList.add("hidden");
  done.classList.remove("hidden");
});

copyCodes.addEventListener("click", function () {
  var all = [].slice.call(document.querySelectorAll("#codes span")).map(function (s) {
    return s.textContent;
  });
  copy(all.join("\n"), copyCodes, "Copied all codes");
});

// Domains that are wired to an identity provider. Everything else gets a password.
var SSO = {
  "northwind.co": "Okta",
  "acme.com": "Microsoft Entra ID",
  "globex.io": "Google Workspace"
};

var form = document.getElementById("gate");
var emailRow = document.getElementById("emailRow");
var email = document.getElementById("email");
var error = document.getElementById("error");
var identity = document.getElementById("identity");
var identityEmail = document.getElementById("identityEmail");
var change = document.getElementById("change");
var passwordRow = document.getElementById("passwordRow");
var password = document.getElementById("password");
var submit = document.getElementById("submit");
var ssoNote = document.getElementById("ssoNote");

var step = "email";

function reset() {
  step = "email";
  emailRow.classList.remove("hidden");
  identity.classList.add("hidden");
  identity.classList.remove("flex");
  passwordRow.classList.add("hidden");
  ssoNote.classList.add("hidden");
  submit.textContent = "Continue";
  email.focus();
}

form.addEventListener("submit", function (e) {
  e.preventDefault();

  if (step === "method") return; // Real apps hand off to the provider here.

  var value = email.value.trim().toLowerCase();
  var valid = /^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/.test(value);
  error.classList.toggle("hidden", valid);
  if (!valid) return;

  step = "method";
  emailRow.classList.add("hidden");
  identityEmail.textContent = value;
  identity.classList.remove("hidden");
  identity.classList.add("flex");

  var provider = SSO[value.split("@")[1]];
  if (provider) {
    submit.textContent = "Continue with " + provider;
    ssoNote.classList.remove("hidden");
    return;
  }

  passwordRow.classList.remove("hidden");
  submit.textContent = "Sign in";
  password.focus();
});

change.addEventListener("click", reset);

var btn = document.getElementById("resendBtn");
var note = document.getElementById("resendNote");
var sends = 1;
var wait = 30;
var left = wait;
var timer;

function label() {
  btn.textContent = left > 0 ? "Resend email in " + left + "s" : "Resend email";
}

function lock(state) {
  btn.disabled = state;
  btn.classList.toggle("cursor-not-allowed", state);
  btn.classList.toggle("text-neutral-400", state);
  btn.classList.toggle("text-neutral-700", !state);
  btn.classList.toggle("hover:bg-neutral-50", !state);
}

function countdown() {
  clearInterval(timer);
  left = wait;
  label();
  lock(true);
  timer = setInterval(function () {
    left -= 1;
    label();
    if (left <= 0) {
      clearInterval(timer);
      lock(false);
    }
  }, 1000);
}

btn.addEventListener("click", function () {
  if (btn.disabled) return;
  sends += 1;
  note.textContent = "Sent " + sends + " times to this address.";
  // Each retry costs a little more patience than the last.
  wait = Math.min(wait * 2, 120);
  countdown();
});

countdown();

var TOTAL = 15 * 60;
var left = TOTAL;

var panel = document.getElementById("lockPanel");
var timer = document.getElementById("lockTimer");
var track = document.getElementById("lockTrack");

function tick() {
  var minutes = Math.floor(left / 60);
  var seconds = left % 60;
  timer.textContent = minutes + ":" + String(seconds).padStart(2, "0");
  track.style.width = (left / TOTAL) * 100 + "%";

  if (left > 0) {
    left -= 1;
    return;
  }

  clearInterval(handle);
  // The lock has lifted — replace the countdown rather than leaving a dead 0:00.
  panel.className = "mt-6 rounded-xl border border-green-200 bg-green-50 p-5 text-center";
  panel.innerHTML =
    '<p class="text-sm font-medium text-green-800">You can try again</p>' +
    '<p class="mt-1 text-xs text-green-700">The lock has lifted. Five more attempts are available.</p>' +
    '<button class="mt-4 rounded-xl bg-neutral-900 px-5 py-2.5 text-sm font-medium text-white">Back to sign in</button>';
}

var handle = setInterval(tick, 1000);
tick();

var MONTHLY = 29;
var DISCOUNT = 0.2;

var buttons = [].slice.call(document.querySelectorAll("#period [data-period]"));
var price = document.getElementById("price");
var note = document.getElementById("billingNote");

var ACTIVE = "rounded-full bg-white px-4 py-1.5 font-medium text-neutral-900 shadow-sm";
var IDLE = "rounded-full px-4 py-1.5 text-neutral-500";

function select(period) {
  buttons.forEach(function (btn) {
    var on = btn.getAttribute("data-period") === period;
    // Keep the pill's inner "Save 20%" badge — only the button's own classes swap.
    btn.className = on ? ACTIVE : IDLE;
  });

  if (period === "annual") {
    var perMonth = Math.round(MONTHLY * (1 - DISCOUNT));
    price.textContent = "$" + perMonth;
    note.textContent = "Billed annually at $" + perMonth * 12 + ". Cancel anytime.";
  } else {
    price.textContent = "$" + MONTHLY;
    note.textContent = "Billed monthly. Cancel anytime.";
  }
}

buttons.forEach(function (btn) {
  btn.addEventListener("click", function () {
    select(btn.getAttribute("data-period"));
  });
});

select("monthly");

// Pricing model — the single place to change rates.
var PLATFORM_FEE = 49;   // flat monthly fee
var RATE_PER_1K  = 0.05; // metered rate beyond the included tier
var INCLUDED     = 500000;
var PER_SEAT     = 12;
var MIN_CALLS    = 100000;
var MAX_CALLS    = 10000000;

var calls = document.getElementById("calls");
var seats = document.getElementById("seats");

// Square the slider position so the low end of the range gets more travel —
// most teams live nearer 100K than 10M, and a linear map buries that end.
function callsFor(position) {
  var t = position / 100;
  return Math.round(MIN_CALLS + t * t * (MAX_CALLS - MIN_CALLS));
}

function formatCalls(n) {
  return n >= 1000000 ? (n / 1000000).toFixed(1) + "M" : Math.round(n / 1000) + "K";
}

function money(n) {
  return "$" + Math.round(n).toLocaleString("en-US");
}

function render() {
  var n = callsFor(Number(calls.value));
  var seatCount = Number(seats.value);
  var metered = Math.max(0, n - INCLUDED) / 1000 * RATE_PER_1K;
  var seatCost = seatCount * PER_SEAT;

  document.getElementById("callsOut").textContent = formatCalls(n);
  document.getElementById("seatsOut").textContent = seatCount;
  document.getElementById("callsRow").textContent = formatCalls(n) + " calls";
  document.getElementById("callsCost").textContent = money(metered);
  document.getElementById("seatsRow").textContent =
    seatCount + (seatCount === 1 ? " seat" : " seats");
  document.getElementById("seatsCost").textContent = money(seatCost);
  document.getElementById("total").textContent = money(PLATFORM_FEE + metered + seatCost);
}

calls.addEventListener("input", render);
seats.addEventListener("input", render);
render();

var BASE = 99;

var boxes = [].slice.call(document.querySelectorAll("#addons input[type=checkbox]"));
var total = document.getElementById("total");
var checkout = document.getElementById("checkout");

var SELECTED = "flex cursor-pointer items-center gap-4 rounded-xl border border-neutral-900 bg-white p-4 ring-4 ring-neutral-900/10";
var IDLE = "flex cursor-pointer items-center gap-4 rounded-xl border border-neutral-200 bg-white p-4 hover:bg-neutral-50";

function render() {
  var sum = BASE;
  var picked = 0;

  boxes.forEach(function (box) {
    var row = box.closest("label");
    if (box.checked) {
      sum += Number(box.getAttribute("data-price"));
      picked += 1;
    }
    row.className = box.checked ? SELECTED : IDLE;
  });

  total.textContent = "$" + sum;
  checkout.textContent =
    picked === 0
      ? "Continue to checkout"
      : "Continue with " + picked + " add-" + (picked === 1 ? "on" : "ons");
}

boxes.forEach(function (box) {
  box.addEventListener("change", render);
});

render();

// List rate the discounts are measured against.
var LIST_RATE = 0.02;
var MAX_PACKS = 20;

var packs = [].slice.call(document.querySelectorAll("#packs input"));
var minus = document.getElementById("minus");
var plus = document.getElementById("plus");
var qtyOut = document.getElementById("qty");
var creditsOut = document.getElementById("sumCredits");
var rateOut = document.getElementById("sumRate");
var savingRow = document.getElementById("savingRow");
var savingOut = document.getElementById("sumSaving");
var totalOut = document.getElementById("sumTotal");

var qty = 1;

function money(n) {
  return "$" + n.toLocaleString("en-US");
}

function render() {
  var chosen = packs.filter(function (p) { return p.checked; })[0] || packs[0];
  var credits = Number(chosen.getAttribute("data-credits")) * qty;
  var total = Number(chosen.getAttribute("data-price")) * qty;
  var saving = Math.round(credits * LIST_RATE - total);

  qtyOut.textContent = qty;
  creditsOut.textContent = credits.toLocaleString("en-US");
  rateOut.textContent = "$" + (total / credits).toFixed(3) + " / credit";
  totalOut.textContent = money(total);

  // No discount on the smallest pack — hide the row rather than show a zero.
  savingRow.classList.toggle("hidden", saving <= 0);
  savingOut.textContent = "−" + money(saving);

  minus.disabled = qty === 1;
  plus.disabled = qty === MAX_PACKS;
  [minus, plus].forEach(function (b) { b.classList.toggle("opacity-30", b.disabled); });
}

packs.forEach(function (p) { p.addEventListener("change", render); });
minus.addEventListener("click", function () { qty = Math.max(1, qty - 1); render(); });
plus.addEventListener("click", function () { qty = Math.min(MAX_PACKS, qty + 1); render(); });

render();

// Indicative rates — in production these come from your billing provider.
var CURRENCIES = {
  USD: { rate: 1, locale: "en-US", step: 1, note: "Prices in US dollars, excluding sales tax." },
  EUR: { rate: 0.92, locale: "de-DE", step: 1, note: "Prices in euro, excluding VAT. Reverse charge applies to EU businesses." },
  GBP: { rate: 0.79, locale: "en-GB", step: 1, note: "Prices in pounds sterling, excluding UK VAT." },
  JPY: { rate: 152, locale: "ja-JP", step: 100, note: "Prices in yen, consumption tax included." },
  INR: { rate: 84, locale: "en-IN", step: 100, note: "Prices in rupees, excluding 18% GST." }
};

var select = document.getElementById("currency");
var note = document.getElementById("taxNote");
var amounts = [].slice.call(document.querySelectorAll("[data-usd]"));

function render(code) {
  var c = CURRENCIES[code];
  var format = new Intl.NumberFormat(c.locale, {
    style: "currency",
    currency: code,
    maximumFractionDigits: 0
  });

  amounts.forEach(function (el) {
    var converted = Number(el.getAttribute("data-usd")) * c.rate;
    // Round to the currency's natural increment so nothing reads like 11.04.
    var rounded = Math.max(c.step, Math.round(converted / c.step) * c.step);
    el.textContent = format.format(rounded);
  });

  note.textContent = c.note;
}

select.addEventListener("change", function () { render(select.value); });
render(select.value);

var UNIT = 12;
var MIN = 2;
var MAX = 250;
var seats = 5;

var countEl = document.getElementById("seatCount");
var lineEl = document.getElementById("seatLine");
var subtotalEl = document.getElementById("seatSubtotal");
var totalEl = document.getElementById("seatTotal");
var row = document.getElementById("discountRow");
var label = document.getElementById("discountLabel");
var value = document.getElementById("discountValue");
var minus = document.getElementById("seatMinus");
var plus = document.getElementById("seatPlus");

function rate() {
  if (seats >= 50) return 0.2;
  if (seats >= 10) return 0.1;
  return 0;
}

function money(n) {
  return "$" + n.toLocaleString("en-US", { maximumFractionDigits: 0 });
}

function render() {
  var subtotal = seats * UNIT;
  var off = subtotal * rate();

  countEl.textContent = seats;
  lineEl.textContent = seats + (seats === 1 ? " seat × " : " seats × ") + money(UNIT);
  subtotalEl.textContent = money(subtotal);
  totalEl.textContent = money(subtotal - off);

  // The discount line only earns its space once there is a discount.
  row.classList.toggle("hidden", off === 0);
  row.classList.toggle("flex", off > 0);
  label.textContent = "Volume discount (" + Math.round(rate() * 100) + "%)";
  value.textContent = "−" + money(off);

  minus.disabled = seats <= MIN;
  plus.disabled = seats >= MAX;
}

minus.addEventListener("click", function () {
  seats = Math.max(MIN, seats - 1);
  render();
});

plus.addEventListener("click", function () {
  seats = Math.min(MAX, seats + 1);
  render();
});

render();

var DAYS_LEFT = 18;
var CYCLE = 30;
var CURRENT = 19;

var rows = Array.prototype.slice.call(document.querySelectorAll(".plan-row"));
var label = document.getElementById("prorateLabel");
var charge = document.getElementById("prorateCharge");
var credit = document.getElementById("prorateCredit");
var total = document.getElementById("prorateTotal");
var next = document.getElementById("prorateNext");

function money(n) {
  return "$" + n.toFixed(2);
}

function select(row) {
  rows.forEach(function (r) {
    var on = r === row;
    r.classList.toggle("border-neutral-900", on);
    r.classList.toggle("ring-1", on);
    r.classList.toggle("ring-neutral-900", on);
    r.querySelector(".dot").classList.toggle("border-neutral-900", on);
    r.querySelector(".dot span").classList.toggle("opacity-0", !on);
  });

  var price = Number(row.dataset.price);
  var share = DAYS_LEFT / CYCLE;
  var newCharge = price * share;
  var unused = CURRENT * share;

  label.textContent = row.querySelector("span span").textContent.trim() + ", " + DAYS_LEFT + " days remaining";
  charge.textContent = money(newCharge);
  credit.textContent = "−" + money(unused);
  // Downgrades leave a credit rather than a charge; never show a negative total.
  total.textContent = money(Math.max(newCharge - unused, 0));
  next.textContent = "Then " + money(price) + " on 14 March, and monthly after that.";
}

rows.forEach(function (row) {
  row.addEventListener("click", function () {
    select(row);
  });
});

select(rows[1]);

var TIERS = [
  { volume: "10k", name: "Starter", price: "$0", note: "Includes 10k events, 30-day retention." },
  { volume: "100k", name: "Growth", price: "$49", note: "Includes 100k events, 90-day retention." },
  { volume: "1M", name: "Scale", price: "$199", note: "Includes 1M events, 1-year retention." },
  { volume: "10M", name: "Enterprise", price: "$690", note: "Includes 10M events, unlimited retention." },
];

var range = document.getElementById("volumeRange");
var value = document.getElementById("volumeValue");
var name = document.getElementById("planName");
var price = document.getElementById("planPrice");
var note = document.getElementById("planNote");
var features = Array.prototype.slice.call(document.querySelectorAll(".feature"));

function render() {
  var i = Number(range.value);
  var tier = TIERS[i];

  value.textContent = tier.volume;
  name.textContent = tier.name;
  price.textContent = tier.price;
  note.textContent = tier.note;

  features.forEach(function (li) {
    // Features from higher tiers stay visible, just clearly out of reach.
    var locked = Number(li.dataset.tier) > i;
    li.classList.toggle("text-neutral-300", locked);
    li.classList.toggle("text-neutral-700", !locked);
  });
}

range.addEventListener("input", render);
render();

var boxes = Array.prototype.slice.call(document.querySelectorAll(".module input"));
var rows = document.getElementById("bundleRows");
var discountRow = document.getElementById("bundleDiscount");
var discountLabel = document.getElementById("bundleDiscountLabel");
var discountValue = document.getElementById("bundleDiscountValue");
var totalEl = document.getElementById("bundleTotal");
var cta = document.getElementById("bundleCta");

function money(n) {
  return "$" + n.toFixed(n % 1 === 0 ? 0 : 2);
}

function rate(count) {
  if (count >= 5) return 0.15;
  if (count >= 3) return 0.1;
  return 0;
}

function sync() {
  var chosen = boxes.filter(function (b) {
    return b.checked;
  });

  rows.innerHTML = chosen
    .map(function (b) {
      return (
        '<div class="flex items-center justify-between text-neutral-600">' +
        "<span>" + b.dataset.name + "</span>" +
        '<span class="font-mono text-neutral-900">' + money(Number(b.dataset.price)) + "</span>" +
        "</div>"
      );
    })
    .join("");

  var subtotal = chosen.reduce(function (sum, b) {
    return sum + Number(b.dataset.price);
  }, 0);
  var off = subtotal * rate(chosen.length);

  discountRow.classList.toggle("hidden", off === 0);
  discountRow.classList.toggle("flex", off > 0);
  discountLabel.textContent = "Bundle discount (" + Math.round(rate(chosen.length) * 100) + "%)";
  discountValue.textContent = "−" + money(off);

  totalEl.textContent = money(subtotal - off);
  cta.textContent = "Continue with " + chosen.length + (chosen.length === 1 ? " module" : " modules");

  boxes.forEach(function (b) {
    var card = b.closest(".module");
    card.classList.toggle("border-neutral-900", b.checked);
    card.classList.toggle("bg-neutral-50", b.checked);
    card.classList.toggle("border-neutral-200", !b.checked);
  });
}

boxes.forEach(function (b) {
  b.addEventListener("change", sync);
});

sync();

var input = document.getElementById("scaleInput");
var range = document.getElementById("scaleRange");
var cta = document.getElementById("scaleCta");

function clamp(value) {
  var n = Number(value);
  if (!n || n < 2) return 2;
  return Math.min(n, 100);
}

function sync(value) {
  var amount = clamp(value);
  input.value = amount;
  range.value = amount;
  cta.textContent = "Support at $" + amount + " a month";
}

input.addEventListener("input", function () {
  // Let the field be briefly empty while typing rather than snapping to 2.
  if (input.value === "") return;
  sync(input.value);
});

input.addEventListener("blur", function () {
  sync(input.value);
});

range.addEventListener("input", function () {
  sync(range.value);
});

var track = document.getElementById("track");
var prev = document.getElementById("prev");
var next = document.getElementById("next");
var dots = document.getElementById("dots");
var cards = [].slice.call(track.children);

var ACTIVE = "h-2 w-6 rounded-full bg-neutral-900 transition-all";
var IDLE = "h-2 w-2 rounded-full bg-neutral-300 transition-all";

// One card plus the gap between two of them — the distance one arrow press moves.
function stride() {
  if (cards.length < 2) return track.clientWidth;
  return cards[1].offsetLeft - cards[0].offsetLeft;
}

cards.forEach(function (card, i) {
  var dot = document.createElement("button");
  dot.className = IDLE;
  dot.setAttribute("aria-label", "Go to slide " + (i + 1));
  dot.addEventListener("click", function () {
    track.scrollTo({ left: card.offsetLeft - cards[0].offsetLeft, behavior: "smooth" });
  });
  dots.appendChild(dot);
});

function sync() {
  var index = Math.round(track.scrollLeft / stride());
  [].slice.call(dots.children).forEach(function (dot, i) {
    dot.className = i === index ? ACTIVE : IDLE;
  });

  var atStart = track.scrollLeft < 4;
