var section = document.getElementById("countSection");
var counters = Array.prototype.slice.call(section.querySelectorAll(".count"));
var reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

function format(value, decimals) {
  return value.toLocaleString("en-US", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

function run(el) {
  var target = Number(el.dataset.target);
  var decimals = Number(el.dataset.decimals);

  if (reduced) {
    el.textContent = format(target, decimals);
    return;
  }

  var duration = 1200;
  var start = performance.now();

  function frame(now) {
    var t = Math.min((now - start) / duration, 1);
    // Ease-out cubic: fast at first, settles gently on the real figure.
    var eased = 1 - Math.pow(1 - t, 3);
    el.textContent = format(target * eased, decimals);
    if (t < 1) requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);
}

var observer = new IntersectionObserver(
  function (entries) {
    entries.forEach(function (entry) {
      if (!entry.isIntersecting) return;
      counters.forEach(run);
      observer.disconnect();
    });
  },
  { threshold: 0.35 }
);

observer.observe(section);

var CIRCUMFERENCE = 2 * Math.PI * 42;
var rings = Array.prototype.slice.call(document.querySelectorAll(".ring"));

rings.forEach(function (ring) {
  ring.style.strokeDasharray = CIRCUMFERENCE.toFixed(1);
  ring.style.strokeDashoffset = CIRCUMFERENCE.toFixed(1);
});

// Set the target on the next frame so the transition has somewhere to travel.
requestAnimationFrame(function () {
  rings.forEach(function (ring) {
    var value = Number(ring.dataset.value) / 100;
    ring.style.strokeDashoffset = (CIRCUMFERENCE * (1 - value)).toFixed(1);
  });
});

