  if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
  if (tabs.indexOf(document.activeElement) === -1) return;
  e.preventDefault();
  var next = e.key === "ArrowRight" ? (index + 1) % tabs.length : (index - 1 + tabs.length) % tabs.length;
  tabs[next].focus();
  activate(next);
});

