function apply(state) {
  if (state === compact) return;
  compact = state;

  nav.classList.toggle("bg-white", state);
  nav.classList.toggle("shadow-sm", state);
  nav.classList.toggle("border-b", state);
  nav.classList.toggle("border-neutral-200", state);

