var body = document.getElementById("tableBody");
var rows = [].slice.call(body.querySelectorAll("tr"));
var search = document.getElementById("tableSearch");
var counter = document.getElementById("rowCount");
var empty = document.getElementById("tableEmpty");
var headers = [].slice.call(document.querySelectorAll("[data-sort]"));

var sortColumn = null;
var ascending = true;

function cellValue(row, index) {
  var cell = row.children[index];
  // Dates carry a sortable ISO value; everything else sorts on its text.
  return cell.getAttribute("data-date") || cell.textContent.trim().toLowerCase();
}

function render() {
  var query = search.value.trim().toLowerCase();
  var visible = 0;

  rows.forEach(function (row) {
    var match = !query || row.textContent.toLowerCase().indexOf(query) !== -1;
    row.classList.toggle("hidden", !match);
    if (match) visible += 1;
  });

  counter.textContent = visible;
  empty.classList.toggle("hidden", visible > 0);
}

headers.forEach(function (header) {
  header.addEventListener("click", function () {
    var index = Number(header.getAttribute("data-sort"));
    ascending = sortColumn === index ? !ascending : true;
    sortColumn = index;

    headers.forEach(function (h) {
      h.querySelector("[data-arrow]").textContent =
        h === header ? (ascending ? "↑" : "↓") : "";
    });

    rows
      .slice()
      .sort(function (a, b) {
        var x = cellValue(a, index);
        var y = cellValue(b, index);
        if (x === y) return 0;
        return (x > y ? 1 : -1) * (ascending ? 1 : -1);
      })
      .forEach(function (row) { body.appendChild(row); });
  });
});

search.addEventListener("input", render);
render();

