var chart = document.getElementById("chart");
var labels = document.getElementById("chartLabels");
var totalOut = document.getElementById("chartTotal");
var deltaOut = document.getElementById("chartDelta");
var buttons = [].slice.call(document.querySelectorAll("#ranges [data-range]"));

var ACTIVE = "rounded-md bg-white px-2.5 py-1 font-medium text-neutral-900 shadow-sm";
var IDLE = "rounded-md px-2.5 py-1 text-neutral-500";

function draw(range) {
  var set = DATA[range];
  // Scale against the tallest column so the chart always fills its height.
  var tallest = Math.max.apply(
    null,
    set.points.map(function (p) { return p[1] + p[2]; })
  );

  chart.innerHTML = "";
  labels.innerHTML = "";
  var total = 0;

  set.points.forEach(function (point) {
    var name = point[0];
    var fresh = point[1];
    var expansion = point[2];
    total += fresh + expansion;

    // Full-height column so the bars' percentage heights have something to
    // resolve against — an items-end row would collapse them to zero.
    var column = document.createElement("div");
    column.className = "flex h-full flex-1 flex-col justify-end gap-0.5";
    column.title = name + " — new " + fresh + "k, expansion " + expansion + "k";

    var top = document.createElement("span");
    top.className = "rounded-t bg-neutral-900";
    top.style.height = (fresh / tallest) * 100 + "%";

    var bottom = document.createElement("span");
    bottom.className = "rounded-b bg-neutral-300";
    bottom.style.height = (expansion / tallest) * 100 + "%";

    column.appendChild(top);
    column.appendChild(bottom);
    chart.appendChild(column);

    var label = document.createElement("span");
    label.className = "flex-1 text-center";
    label.textContent = name;
    labels.appendChild(label);
  });

  totalOut.textContent = "$" + (total * 1000).toLocaleString("en-US");

  var up = set.delta.indexOf("↑") === 0;
  deltaOut.textContent = set.delta;
  deltaOut.className =
    "ml-1 rounded px-1.5 py-0.5 text-xs font-medium " +
    (up ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700");

  buttons.forEach(function (b) {
    b.className = b.getAttribute("data-range") === range ? ACTIVE : IDLE;
  });
}

buttons.forEach(function (button) {
  button.addEventListener("click", function () {
    draw(button.getAttribute("data-range"));
  });
});

