var pinned = null;

function dotFor(region) {
  return dots.filter(function (dot) {
    return dot.dataset.region === region;
  })[0];
}

function highlight(region, label) {
  dots.forEach(function (dot) {
    var on = dot.dataset.region === region;
    dot.classList.toggle("h-5", on);
    dot.classList.toggle("w-5", on);
    dot.classList.toggle("h-3", !on);
    dot.classList.toggle("w-3", !on);
  });

  var dot = dotFor(region);
  if (!dot || !label) {
    tip.classList.add("hidden");
    return;
  }

  tip.textContent = label;
  tip.style.left = dot.style.left;
  tip.style.top = "calc(" + dot.style.top + " - 34px)";
  tip.classList.remove("hidden");
}

rows.forEach(function (row) {
  row.addEventListener("mouseenter", function () {
    highlight(row.dataset.region, row.dataset.label);
  });

  row.addEventListener("mouseleave", function () {
    // Fall back to whatever is pinned rather than clearing the map entirely.
    if (pinned) highlight(pinned.dataset.region, pinned.dataset.label);
    else highlight("", "");
  });

  row.addEventListener("click", function () {
    pinned = pinned === row ? null : row;
    rows.forEach(function (r) {
      r.classList.toggle("bg-neutral-100", r === pinned);
    });
    if (pinned) highlight(row.dataset.region, row.dataset.label);
    else highlight("", "");
  });
});

