var RULES = {
  fName: function (v) { return v.trim().length > 0; },
  fEmail: function (v) { return v.indexOf("@") > 0 && v.lastIndexOf(".") > v.indexOf("@"); },
  fPassword: function (v) { return v.length >= 10; },
  fCompany: function (v) { return v.trim().length > 0; },
