function fieldsFor(n) {
  return n === 1 ? ["fName", "fEmail", "fPassword"] : ["fCompany"];
}

function valid(n) {
  var ok = fieldsFor(n).every(function (id) {
    return RULES[id](document.getElementById(id).value);
  });
  if (n === 2) ok = ok && document.getElementById("fTerms").checked;
  return ok;
