var rows = [].slice.call(document.querySelectorAll("[data-shortcut]"));
var activeRow = null;
var isApple = /Mac|iPhone|iPad/.test(navigator.platform);
var RESERVED = ["Meta+R", "Meta+T", "Meta+W", "Ctrl+R", "Ctrl+T", "Ctrl+W"];

function label(part) {
  if (part === "Meta") return isApple ? "⌘" : "Win";
  if (part === "Ctrl") return isApple ? "⌃" : "Ctrl";
  if (part === "Alt") return isApple ? "⌥" : "Alt";
  if (part === "Shift") return isApple ? "⇧" : "Shift";
  return part;
}

function render(row) {
  var holder = row.querySelector("[data-keys]");
  var binding = row.getAttribute("data-binding");
  holder.innerHTML = "";
  if (!binding) {
    holder.textContent = "Not set";
    holder.className = "text-xs text-neutral-400";
    return;
  }
  holder.className = "flex gap-1";
  binding.split("+").forEach(function (part) {
    var key = document.createElement("kbd");
    key.className = "min-w-7 rounded-md border border-neutral-200 bg-neutral-50 px-1.5 py-1 text-center text-[11px] font-medium text-neutral-600 shadow-sm";
    key.textContent = label(part);
    holder.appendChild(key);
  });
}

function close(row) {
  row.querySelector("[data-summary]").classList.remove("hidden");
  row.querySelector("[data-recorder]").classList.add("hidden");
  row.querySelector("[data-warning]").className = "text-xs text-neutral-400";
  row.querySelector("[data-warning]").textContent = "Esc cancels · Backspace clears";
  if (activeRow === row) activeRow = null;
}

function open(row) {
  if (activeRow) close(activeRow);
  activeRow = row;
  row.querySelector("[data-summary]").classList.add("hidden");
  row.querySelector("[data-recorder]").classList.remove("hidden");
  row.querySelector("[data-capture]").focus();
}

function combination(event) {
  var parts = [];
  if (event.metaKey) parts.push("Meta");
  if (event.ctrlKey) parts.push("Ctrl");
  if (event.altKey) parts.push("Alt");
  if (event.shiftKey) parts.push("Shift");
  var key = event.key.length === 1 ? event.key.toUpperCase() : event.key;
  if (["Meta", "Control", "Alt", "Shift"].indexOf(key) === -1) parts.push(key);
  return parts.join("+");
}

document.addEventListener("keydown", function (event) {
  if (!activeRow) return;
  event.preventDefault();
  if (event.key === "Escape") return close(activeRow);
  if (event.key === "Backspace") {
    activeRow.setAttribute("data-binding", "");
    render(activeRow);
    return close(activeRow);
  }
  if (["Meta", "Control", "Alt", "Shift"].indexOf(event.key) !== -1) return;

  var binding = combination(event);
  var warning = activeRow.querySelector("[data-warning]");
  var hasModifier = event.metaKey || event.ctrlKey || event.altKey || event.shiftKey;
  if (!hasModifier && /^[A-Z0-9]$/.test(event.key.toUpperCase())) {
    warning.textContent = "Add Ctrl, Alt, Shift, or Meta.";
    warning.className = "text-xs text-red-600";
    return;
  }
  if (RESERVED.indexOf(binding) !== -1) {
    warning.textContent = "That shortcut is reserved by your browser.";
    warning.className = "text-xs text-red-600";
    return;
  }
  var conflict = rows.filter(function (row) {
    return row !== activeRow && row.getAttribute("data-binding") === binding;
  })[0];
  if (conflict) {
    warning.textContent = "Already used by “" + conflict.getAttribute("data-action") + "”.";
    warning.className = "text-xs text-red-600";
    return;
  }

  activeRow.setAttribute("data-binding", binding);
  render(activeRow);
  close(activeRow);
});

rows.forEach(function (row) {
  render(row);
  row.querySelector("[data-change]").addEventListener("click", function () { open(row); });
  row.querySelector("[data-cancel]").addEventListener("click", function () { close(row); });
});

