function paintTrail() {
  trail.innerHTML = "";
  attempts.forEach(function (attempt, index) {
    var chip = document.createElement("span");
    chip.className =
      "rounded-md px-2 py-0.5 font-mono text-[11px] " +
      (attempt.ok ? "bg-green-50 text-green-700" : "bg-red-50 text-red-700");
